import{j as a,u as c,D as M,C as q,P as W,t as T,o as L,v as j,d as O,M as $}from"./index-CF0CIIdJ.js";import{C as k,S as B,a as H,F as J,A as Y}from"./blocks-B6_GBvbN.js";import{D,S as F,B as U}from"./aviation-CJgc16LR.js";import{I as m,E as _}from"./ExpiryCalculator-BXt--1Lw.js";import{S as i,P as K,p as V}from"./index-DlKAg88T.js";const s="Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book.",p="Main Terminal Building, Gate 2, Office TG6B, Grand Central Airport, 3 New Road, Midrand, 1685",A="08h00 to 16h30 Monday to Thursday, and 08h00 to 14h30 on Friday",v="Enter Grand Central Airport at the main gate and go in through the main entrance of the airport building. Take the first right once inside, and ClinoTrend is straight ahead.",R="a resting ECG, vision testing, a hearing test (audiometry) and urine screening",h="A resting ECG, vision testing, a hearing test (audiometry) and urine screening",d="Payment by EFT or card is required at the time of your visit. We accept most medical aids and charge medical aid rates. Self-pay patients receive a quote before treatment.",f="Group bookings for flight schools, cabin crew academies, airlines and employers are arranged in advance. Call 011 568 7979 or email info@clinotrend-health.co.za with the number of people and the dates that suit you.",g="ClinoTrend does not currently issue Class 1 or Class 3. Those classes need a SACAA Senior DAME.",G="https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf",x="https://www.caa.co.za/industry-information/aviation-medicine/",b=["Your South African ID or passport","Any aviation licence you hold, and your logbook if you are renewing","Your most recent aviation medical certificate, if you have one","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"],y={gcDirectory:{name:"Grand Central Airport tenant directory (checked 10 November 2026)",url:"https://www.grandcentral.co.za/tenant-directory/"},lanseriaSchools:{name:"Lanseria International Airport: flying schools (checked 10 November 2026)",url:"https://lanseria.co.za/corporate/pilot-and-aviation-info/flying-schools/"},damesGuide:{name:"SACAA DAMEs guide: Part 67 classes, including the full Class 4 licence list and regulation 67.00.5",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Dames%20Guide.pdf"},sacaaFees:{name:"SACAA fees, charges and levies (Part 187 schedule from 1 October 2026)",url:"https://www.caa.co.za/information-for-the-public/fees/"},brakpan:{name:"Brakpan Aero Club: flight schools at Brakpan airfield (checked 10 November 2026)",url:"https://brakpanaeroclub.co.za/flight-schools/"}},t={fagc:{name:"Grand Central Airport (FAGC), Midrand",note:"Where the clinic is, inside the main terminal. Fly in and park on the apron outside the Gate 2 terminal doors."},fala:{name:"Lanseria International Airport (FALA)",note:"North-west of Johannesburg, with resident flying schools. By road, the N14 and N1 link it to Midrand."},fawb:{name:"Wonderboom National Airport (FAWB)",note:"North of Pretoria, home to several training schools and general aviation operators."},fagm:{name:"Rand Airport (FAGM), Germiston",note:"South-east of central Johannesburg, a general aviation and training airport."},faor:{name:"O.R. Tambo International Airport (FAOR), Kempton Park",note:"Base for airline cabin crew. Linked to Midrand by road, and by Gautrain via Marlboro."},fabb:{name:"Brakpan airfield (FABB), near Benoni",note:"An East Rand general aviation field with flight schools listed by the Brakpan Aero Club."}},S=[{path:"/aviation-medicals/gauteng/",kind:"hub",group:"Gauteng hub",navLabel:"Gauteng",title:"Aviation Medical Examiner Gauteng | Class 2, 4 | ClinoTrend",description:"SACAA Class 2 and Class 4 aviation medicals for Gauteng pilots and cabin crew at Grand Central Airport, Midrand. Routes, tests, fees from R1,500. Book online.",h1:"Aviation medical examiner for Gauteng pilots and cabin crew",eyebrow:"Gauteng aviation medicals",trailName:"Gauteng",lead:"Pilots and cabin crew from across Gauteng come to one clinic, inside the main terminal at Grand Central Airport in Midrand. This page shows which medical to book, how to reach the airport from each part of the province, and what happens on the day.",answer:"ClinoTrend Health & Aviation is inside the main terminal at Grand Central Airport, Midrand, next to the N1 between Johannesburg and Pretoria. Dr A.O. Ndhlovu, a SACAA Regular Designated Aviation Medical Examiner (MR 336), issues Class 2 and Class 4 medicals for student, private and recreational pilots and cabin crew. Book online. Fees start from R1,500.",facts:[`One address only: ${p}.`,"Drive in (N1, New Road or Allandale exit), take the Gautrain to Midrand station then e-hailing or a taxi, or fly in to FAGC.","Class 1 and Class 3 are not currently issued here. They need a SACAA Senior DAME."],body:[{t:"h2",x:"Which aviation medical do you need?",id:"which"},{t:"p",x:"Your licence sets the class, under Part 67 regulation 67.00.2. A Regular DAME such as Dr Ndhlovu may issue Class 2 and Class 4. A Senior DAME may also issue Class 1 and Class 3."},{t:"table",caption:"SACAA medical classes and what is issued at ClinoTrend, Grand Central Airport",head:["Class","Who needs it","At ClinoTrend"],rows:[["Class 2","Student pilots (SPL) and private pilots (PPL) for aeroplane, airship and helicopter, flight engineers, commercial glider and commercial free balloon pilots","Yes: [first medicals and renewals](/aviation-medicals/class-2/)"],["Class 4","Cabin crew, and recreational licences such as microlight, gyroplane, light sport aeroplane, non-commercial glider and non-commercial free balloon","Yes: [cabin crew](/aviation-medicals/class-4-cabin-crew/) and [recreational pilots](/aviation-medicals/recreational-pilots/)"],["Class 1","Commercial (CPL) and airline transport (ATPL) pilots, instrument rating","Not currently. Needs a Senior DAME"],["Class 3","Air traffic controllers, air traffic service assistants, remote pilots (RPL)","Not currently. Needs a Senior DAME"]]},{t:"p",x:"Cabin crew: amended Part 67 lists the cabin crew licence under Class 4, while some SACAA pages still show Class 2. Dr Ndhlovu issues either, so book the class your airline or operator asks for. The [guide to SACAA medical classes](/blog/sacaa-medical-classes-explained/) has the full licence list."},{t:"h2",x:"Getting to Grand Central from around Gauteng",id:"routes"},{t:"p",x:"Grand Central Airport (FAGC) is in Midrand, between Johannesburg and Pretoria, next to the N1. The table gives the usual roads in general terms. Traffic changes the trip a lot, so use a live map on the day and leave a margin. We do not publish journey times."},{t:"table",caption:"Usual roads to Grand Central Airport, 3 New Road, Midrand",head:["Coming from","Usual road","More detail"],rows:[["Johannesburg, Sandton, Randburg, Fourways","N1 north to the New Road or Allandale exit","[Johannesburg page](/aviation-medicals/johannesburg/)"],["Pretoria and Wonderboom","N1 south to the New Road exit","[Pretoria page](/aviation-medicals/pretoria/)"],["Centurion","N1 south, or the R101 through Olifantsfontein","[Centurion page](/aviation-medicals/centurion/)"],["Kempton Park, Benoni, Germiston","R21 and R562, or the N3 north to the N1","[East Rand page](/aviation-medicals/east-rand/)"],["Lanseria and the north-west","N14 east, then the N1 south","[Lanseria page](/aviation-medicals/lanseria/)"],["Midrand suburbs","Local roads to New Road","[Midrand page](/aviation-medicals/midrand/)"]]},{t:"p",x:"By Gautrain, ride to Midrand station and use e-hailing or a taxi to the airport. If you hold a current certificate and fly, you can [fly in to FAGC](/aviation-medicals/fly-in/) and park on the apron outside the Gate 2 terminal doors. Car parking at the terminal is boom-gated."},{t:"h2",x:"What happens at the medical",id:"day"},{t:"ol",items:["[Book a time online](/book/), call 011 568 7979 or WhatsApp 078 255 1405. Medicals are by appointment only, because each one is prepared before you arrive.","Complete the [SACAA application form online](/sacaa-form/). It is emailed only to the practice.",`On the day, Dr Ndhlovu takes your medical history and examines you. ${h} are done on site.`,"If you meet the SACAA standards and no further reports are needed, the certificate is issued at the end of the examination. If more reports are needed, it follows once they are in."]},{t:"p",x:`Most aviation medicals are completed on the same day, depending on your case. Ask how long to allow when you book. The [Aviation Medical Report, CA 67-02(a)](${G}), is completed on the day.`},{t:"h2",x:"Fees and payment",id:"fees"},{t:"p",x:`${s} ${d} More detail is on the [aviation medical cost page](/aviation-medicals/cost/).`},{t:"h2",x:"How to check any examiner in Gauteng",id:"check"},{t:"p",x:`SACAA publishes a list of Regular DAMEs and a list of Senior DAMEs on its [aviation medicine page](${x}). Dr A.O. Ndhlovu is listed as Regular DAME MR 336 at Grand Central Airport. Read [how to check a SACAA medical examiner](/blog/sacaa-medical-examiners-dame/) before you book anywhere.`},{t:"h2",x:"Flight schools, academies and employers",id:"groups"},{t:"p",x:f},{t:"cta",x:"Book an aviation medical at Grand Central"}],airfields:[t.fagc,t.fala,t.fawb,t.fagm,t.faor,t.fabb],bookService:null,bookLabel:"Book an aviation medical",related:["/aviation-medicals/midrand/","/aviation-medicals/johannesburg/","/aviation-medicals/pretoria/","/aviation-medicals/centurion/","/aviation-medicals/east-rand/","/aviation-medicals/lanseria/","/aviation-medicals/fly-in/","/aviation-medicals/class-2/","/aviation-medicals/class-4-cabin-crew/","/aviation-medicals/renewal/","/aviation-medicals/student-pilot/","/aviation-medicals/recreational-pilots/","/aviation-medicals/cost/"],guides:["sacaa-medical-examiners-dame","sacaa-medical-classes-explained","aviation-medical-midrand-johannesburg"],faqs:[{q:"Where can I do an aviation medical in Gauteng?",a:`SACAA lists designated examiners across Gauteng on its aviation medicine page. At ClinoTrend, Dr A.O. Ndhlovu (Regular DAME, MR 336) does Class 2 and Class 4 medicals at ${p}. Book online or call 011 568 7979.`},{q:"Does ClinoTrend have rooms in Johannesburg or Pretoria?",a:"No. The only clinic is at Grand Central Airport in Midrand, next to the N1 between Johannesburg and Pretoria."},{q:"Which aviation medicals are not done at ClinoTrend?",a:"Class 1 and Class 3. They need a SACAA Senior DAME, and ClinoTrend does not currently issue them. The SACAA aviation medicine page links to the list of Senior DAMEs."},{q:"Is the Midrand clinic open on Saturdays?",a:`No. Hours are ${A}, by appointment only. The practice is closed on weekends and public holidays.`},{q:"What should I bring to an aviation medical in Gauteng?",a:"Your ID or passport, any aviation licence and your logbook if you are renewing, your latest medical certificate, a list of every medicine you take, glasses, contact lenses or hearing aids if you use them, and recent reports from your doctor if you have a medical condition."}],areaServed:["Midrand","Johannesburg","Pretoria","Centurion","Sandton","Randburg","Kempton Park","Benoni","Germiston"],keyword:"aviation medical examiner gauteng",secondary:["aviation medical near me","dame near me","sacaa medical examiners contact details"],sources:[i.classes,i.avmed,i.register,i.validityReg],llmsSummary:"Gauteng hub: ClinoTrend is at Grand Central Airport, Midrand, only. Dr A.O. Ndhlovu (Regular DAME, MR 336) issues SACAA Class 2 and Class 4 medicals. Usual roads from Johannesburg, Pretoria, Centurion, the East Rand and Lanseria, Gautrain to Midrand station, fly-in to FAGC, what happens at the medical, fees from R1,500. Class 1 and Class 3 are not currently issued."},{path:"/aviation-medicals/midrand/",kind:"area",group:"Areas",navLabel:"Midrand",title:"Aviation Medical Midrand | Grand Central | ClinoTrend",description:"Aviation medical in Midrand, inside the Grand Central Airport terminal: SACAA Class 2 and Class 4 with Dr A.O. Ndhlovu (MR 336). Directions, Gautrain, fly-in.",h1:"Aviation medical in Midrand, inside Grand Central Airport",eyebrow:"Midrand",trailName:"Midrand",lead:"The aviation medical rooms are on the airport itself. If you live, work or fly in Midrand, you can do a first Class 2, a renewal or a cabin crew medical without leaving Grand Central.",answer:`ClinoTrend's aviation medical rooms are at ${p}. Dr A.O. Ndhlovu, a SACAA Regular DAME (MR 336), does Class 2 and Class 4 medicals by appointment, ${A}. Fees start from R1,500.`,facts:["Inside the terminal: through the main entrance, first right, straight ahead.","Fly in to FAGC and park on the apron outside the Gate 2 terminal doors.","Book online, by phone on 011 568 7979 or on WhatsApp 078 255 1405."],body:[{t:"h2",x:"Finding the clinic at Grand Central Airport",id:"find"},{t:"p",x:`${v} The address for maps and e-hailing is Grand Central Airport, 3 New Road, Midrand, 1685. Ask for the Main Terminal Building, Gate 2, Office TG6B. Car parking at the terminal is boom-gated.`},{t:"p",x:"From the N1, take the New Road or Allandale exit and follow New Road to the airport. From Midrand suburbs such as Halfway House, Vorna Valley, Carlswald, Noordwyk and Kyalami, local roads lead to New Road. Traffic around the N1 and New Road can be heavy at peak times, so check a live map and leave a margin."},{t:"h2",x:"By Gautrain to Midrand station",id:"gautrain"},{t:"p",x:"Midrand station is on the Gautrain north-south line, between Centurion and Marlboro. From the station, use e-hailing or a taxi to Grand Central Airport. We do not publish a time for that last leg, because it depends on traffic. Contact the practice for directions if you need them."},{t:"h2",x:"A clinic on a training airport",id:"airport"},{t:"p",x:"Grand Central (FAGC) is a general aviation airport. Its own [tenant directory](https://www.grandcentral.co.za/tenant-directory/) lists training organisations based there, including SkyHawk Aviation, Lanseria Flight Centre, Excellentia Airline Academy, Delta-Delta Training (cabin crew) and Sim Central (checked 10 November 2026). Students and trainees from these and any other school can book here, one at a time or as a group arranged in advance."},{t:"p",x:"Because the clinic is inside the terminal, a student can fit a first Class 2 around lessons, and a private pilot can renew without leaving the airport. Book first: medicals are by appointment only, because each one is prepared before you arrive."},{t:"h2",x:"Medicals done in Midrand",id:"medicals"},{t:"ul",items:["[Class 2 medical](/aviation-medicals/class-2/): student pilots (SPL), private pilots (PPL) and the other Class 2 licences, first issue and renewal.","[Cabin crew medical](/aviation-medicals/class-4-cabin-crew/): Class 4 or Class 2, as the airline or operator asks.","[Recreational pilot medical](/aviation-medicals/recreational-pilots/): Class 4 for microlight, gyroplane, light sport aeroplane, glider and balloon licences.","[Renewals](/aviation-medicals/renewal/): book a few weeks before the expiry date on your certificate."]},{t:"p",x:g},{t:"h2",x:"Before you come",id:"before"},{t:"p",x:"Complete the [SACAA application form online](/sacaa-form/). Rest well, and avoid caffeine, tobacco and high sugar meals beforehand, as they can affect urine and ECG results. Arrive a little early, and bring:"},{t:"ul",items:b},{t:"p",x:`${s} The longer [Midrand and Johannesburg guide](/blog/aviation-medical-midrand-johannesburg/) covers the examination in more detail.`},{t:"cta",x:"Book your medical in Midrand"}],airfields:[t.fagc,t.fala,t.faor],bookService:null,bookLabel:"Book an aviation medical",related:["/aviation-medicals/gauteng/","/aviation-medicals/centurion/","/aviation-medicals/johannesburg/","/aviation-medicals/fly-in/","/aviation-medicals/class-2/","/aviation-medicals/student-pilot/"],guides:["aviation-medical-midrand-johannesburg","student-pilot-medical-south-africa","renew-sacaa-class-2-medical"],faqs:[{q:"Where exactly is ClinoTrend at Grand Central Airport?",a:`In the Main Terminal Building, Gate 2, Office TG6B. ${v}`},{q:"Is there parking at the terminal for patients who drive?",a:"Yes. Car parking at the Grand Central terminal is boom-gated. Follow New Road to the airport and go to the Main Terminal Building, Gate 2."},{q:"Can I walk in for an aviation medical in Midrand?",a:"No. Medicals are by appointment only, because each one is prepared before your visit. Book online, by phone on 011 568 7979 or on WhatsApp 078 255 1405."},{q:"Which Gautrain station is nearest to the clinic?",a:"Midrand station. From there, use e-hailing or a taxi to Grand Central Airport, 3 New Road. Contact the practice for directions if you need them."}],areaServed:["Midrand","Halfway House","Kyalami","Vorna Valley"],keyword:"aviation medical midrand",secondary:["aviation medical examiner midrand","grand central airport","class 2 medical midrand"],sources:[i.register,y.gcDirectory,i.classesReg],llmsSummary:"Midrand: ClinoTrend is inside the Grand Central Airport main terminal (Gate 2, Office TG6B, 3 New Road). Directions inside the airport, N1 New Road or Allandale exit, boom-gated terminal parking, Gautrain to Midrand station then e-hailing or taxi, fly-in apron parking outside the Gate 2 doors. Class 2 and Class 4 by appointment, from R1,500."},{path:"/aviation-medicals/johannesburg/",kind:"area",group:"Areas",navLabel:"Johannesburg",title:"Aviation Medical Johannesburg | Class 2 and 4 | ClinoTrend",description:"Johannesburg, Sandton and Randburg pilots and cabin crew: SACAA Class 2 and Class 4 medicals at Grand Central Airport, Midrand, on the N1 or by Gautrain.",h1:"Aviation medical for Johannesburg pilots and cabin crew",eyebrow:"Johannesburg, Sandton, Randburg, Fourways",trailName:"Johannesburg",lead:"There are no ClinoTrend rooms in Johannesburg itself. Johannesburg pilots, students and cabin crew travel north to Grand Central Airport in Midrand, by the N1 or by Gautrain, for Class 2 and Class 4 medicals.",answer:"ClinoTrend has no Johannesburg rooms. Johannesburg pilots and cabin crew come to Grand Central Airport in Midrand, north of the city on the N1, where Dr A.O. Ndhlovu (SACAA Regular DAME, MR 336) does Class 2 and Class 4 medicals by appointment. From Park, Rosebank or Sandton, the Gautrain runs to Midrand station.",facts:["Usual road: N1 north to the New Road or Allandale exit in Midrand.","Gautrain: Park, Rosebank, Sandton and Marlboro to Midrand station, then e-hailing or a taxi.",s],body:[{t:"h2",x:"Driving from Johannesburg to Grand Central",id:"drive"},{t:"p",x:"Every Johannesburg route ends on the N1 north and the New Road or Allandale exit in Midrand. The table shows the usual way onto the N1 from each part of the city, in general terms. Journey times change a lot with N1 traffic, so check a live map and leave a margin. We do not publish fixed travel times."},{t:"table",caption:"Johannesburg to Grand Central Airport, 3 New Road, Midrand",head:["Coming from","Usual way"],rows:[["Inner city, Parktown, Rosebank","M1 north to the Buccleuch interchange, then the N1 north to Midrand"],["Sandton, Sunninghill, Woodmead","Join the N1 north, then the New Road or Allandale exit"],["Randburg, Northcliff, Fourways","N1 western bypass north to Buccleuch, then the N1 north. From Fourways a live map may pick local roads east toward Midrand"],["Soweto and the southern suburbs","N1 western bypass north, or the M1 north, then the N1 to Midrand"]]},{t:"h2",x:"By Gautrain from Park, Rosebank or Sandton",id:"gautrain"},{t:"p",x:"The Gautrain north-south line runs from Park station through Rosebank, Sandton and Marlboro to Midrand. From Midrand station, use e-hailing or a taxi to Grand Central Airport. That keeps the main part of the trip off the N1. Contact the practice for directions if you need them."},{t:"h2",x:"Who books from Johannesburg",id:"who"},{t:"p",x:"Students training at Rand Airport, Lanseria or Grand Central book a first [Class 2 medical](/aviation-medicals/class-2/) before solo flight. Private pilots renew a Class 2 a few weeks before the date on their certificate. Cabin crew with Johannesburg addresses book [Class 4 or Class 2](/aviation-medicals/class-4-cabin-crew/), whichever the airline or operator asks for. Recreational pilots book a [Class 4](/aviation-medicals/recreational-pilots/)."},{t:"p",x:"A student from any flight school can book. Schools that want several students seen together can arrange a group booking in advance."},{t:"h2",x:"If you need Class 1 or Class 3",id:"class1"},{t:"p",x:`If you need Class 1 for a CPL, ATPL or instrument rating, or Class 3 for air traffic services or a remote pilot licence, look for a Senior DAME on the [SACAA list](${x}). ${g} A student working toward a commercial licence uses Class 2 for the SPL and PPL stages; see the [student pilot medical](/aviation-medicals/student-pilot/) page.`},{t:"h2",x:"Fees and booking",id:"book"},{t:"p",x:`${s} ${d} Book online and your time is confirmed on screen as soon as you choose a free slot.`},{t:"cta",x:"Book your medical from Johannesburg"}],airfields:[t.fagm,t.fala,t.fagc,t.faor],bookService:null,bookLabel:"Book an aviation medical",related:["/aviation-medicals/gauteng/","/aviation-medicals/midrand/","/aviation-medicals/east-rand/","/aviation-medicals/lanseria/","/aviation-medicals/class-2/","/aviation-medicals/renewal/"],guides:["aviation-medical-midrand-johannesburg","renew-sacaa-class-2-medical","sacaa-medical-examiners-dame"],faqs:[{q:"Is there a ClinoTrend aviation medical clinic in Johannesburg?",a:`No. The only address is ${p}. Johannesburg patients reach it by the N1 north or by Gautrain to Midrand station.`},{q:"How do I get from Sandton to the clinic without driving?",a:"Take the Gautrain north from Sandton, through Marlboro, to Midrand station. From there, use e-hailing or a taxi to Grand Central Airport, 3 New Road."},{q:"I train at Rand Airport. Can I do my Class 2 at Grand Central?",a:"Yes. Students from any flight school can book a Class 2 at ClinoTrend. Tell us if your school wants several students seen as a group, which is arranged in advance."},{q:"How much is an aviation medical for a Johannesburg pilot?",a:s}],areaServed:["Johannesburg","Sandton","Randburg","Fourways","Rosebank","Soweto"],keyword:"aviation medical johannesburg",secondary:["aviation medical examiner johannesburg","pilot medical johannesburg","aviation medical sandton"],sources:[i.register,i.classesReg,i.avmed],llmsSummary:"Johannesburg: no Johannesburg rooms. Johannesburg, Sandton, Randburg and Fourways pilots and cabin crew go to Grand Central Airport, Midrand: N1 north to the New Road or Allandale exit, or Gautrain (Park, Rosebank, Sandton, Marlboro) to Midrand station then e-hailing or taxi. Class 2 and Class 4 only, from R1,500."},{path:"/aviation-medicals/pretoria/",kind:"area",group:"Areas",navLabel:"Pretoria",title:"Aviation Medical Pretoria | Class 2 and 4 | ClinoTrend",description:"Pretoria and Wonderboom pilots and cabin crew: SACAA Class 2 and Class 4 medicals at Grand Central Airport, Midrand, by the N1 south or Gautrain. From R1,500.",h1:"Aviation medical for Pretoria and Wonderboom pilots",eyebrow:"Pretoria and Wonderboom",trailName:"Pretoria",lead:"ClinoTrend has no rooms in Pretoria. Pretoria and Wonderboom pilots, students and cabin crew come south to Grand Central Airport in Midrand for Class 2 and Class 4 medicals, by the N1 or by Gautrain.",answer:"ClinoTrend has no Pretoria rooms. Pretoria and Wonderboom pilots come south on the N1 to the New Road exit, or take the Gautrain from Hatfield or Pretoria station to Midrand, for Class 2 and Class 4 medicals with Dr A.O. Ndhlovu (SACAA Regular DAME, MR 336) at Grand Central Airport. Fees start from R1,500.",facts:["Usual road: N1 south to the New Road exit in Midrand.","Gautrain: Hatfield, Pretoria and Centurion stations to Midrand station, then e-hailing or a taxi.","Book online, call 011 568 7979 or WhatsApp 078 255 1405."],body:[{t:"h2",x:"From Pretoria to Grand Central Airport",id:"drive"},{t:"p",x:"From central Pretoria, Hatfield, Menlyn and the eastern suburbs, the usual road is the N1 south past Centurion to the New Road exit in Midrand. From the northern suburbs and Wonderboom, join the N1 south the way a live map suggests. N1 traffic between Pretoria and Midrand changes through the day, so check a live map before you leave. We do not publish fixed travel times."},{t:"h2",x:"By Gautrain from Hatfield or Pretoria station",id:"gautrain"},{t:"p",x:"The Gautrain north-south line runs from Hatfield through Pretoria and Centurion stations to Midrand. From Midrand station, use e-hailing or a taxi to Grand Central Airport, 3 New Road. Contact the practice for directions if you need them."},{t:"h2",x:"Wonderboom students and private pilots",id:"wonderboom"},{t:"p",x:"Wonderboom National Airport (FAWB), north of Pretoria, is home to several flight training schools and general aviation operators. Students there need a [Class 2 medical](/aviation-medicals/class-2/) and a Student Pilot Licence before the first solo flight. Under amended Part 61 (regulation 61.02.1), an SPL applicant must be at least 15, hold a valid medical certificate and be registered with an approved training organisation. The [student pilot medical page](/aviation-medicals/student-pilot/) covers the order of steps."},{t:"p",x:"Private pilots based at Wonderboom renew their Class 2 at Grand Central the same way. Book a few weeks before the date on your certificate, so any extra report has time to come in. See [Class 2 renewal](/aviation-medicals/renewal/)."},{t:"h2",x:"Pretoria cabin crew and recreational pilots",id:"class4"},{t:"p",x:"Cabin crew who live in Pretoria book a [cabin crew medical](/aviation-medicals/class-4-cabin-crew/), Class 4 or Class 2 as the airline or operator asks. Microlight, gyroplane, light sport, glider and balloon pilots book a [recreational Class 4](/aviation-medicals/recreational-pilots/)."},{t:"h2",x:"If you need a Class 1 in Pretoria",id:"class1"},{t:"p",x:`Class 1 for a CPL, ATPL or instrument rating, and Class 3 for air traffic services, need a SACAA Senior DAME. ${g} The [SACAA aviation medicine page](${x}) links to the list of Senior DAMEs, several of whom practise in and around Pretoria.`},{t:"h2",x:"Fees and booking",id:"book"},{t:"p",x:`${s} ${d}`},{t:"cta",x:"Book your medical from Pretoria"}],airfields:[t.fawb,t.fagc,t.fala],bookService:null,bookLabel:"Book an aviation medical",related:["/aviation-medicals/gauteng/","/aviation-medicals/centurion/","/aviation-medicals/midrand/","/aviation-medicals/student-pilot/","/aviation-medicals/class-2/","/aviation-medicals/renewal/"],guides:["student-pilot-medical-south-africa","sacaa-medical-examiners-dame","class-2-medical-validity-by-age"],faqs:[{q:"Does ClinoTrend have rooms in Pretoria?",a:`No. The only clinic is at ${p}. From Pretoria, take the N1 south to the New Road exit, or the Gautrain to Midrand station.`},{q:"I fly from Wonderboom. Can I do my medical at Grand Central?",a:"Yes. Pilots and students from any airfield or school can book a Class 2 or Class 4 at ClinoTrend. Where you train does not change where you may do your medical."},{q:"Which Gautrain stations connect Pretoria to the clinic?",a:"Hatfield, Pretoria and Centurion stations are on the line to Midrand station. From Midrand station, use e-hailing or a taxi to Grand Central Airport."},{q:"Where do Pretoria pilots get a Class 1 medical?",a:"From a SACAA Senior DAME. ClinoTrend does not currently issue Class 1. The SACAA aviation medicine page links to the Senior DAME list."}],areaServed:["Pretoria","Hatfield","Menlyn","Wonderboom"],keyword:"aviation medical pretoria",secondary:["aviation medical examiner pretoria","pilot medical pretoria","wonderboom aviation medical"],sources:[i.register,i.spl,i.classesReg,i.avmed],llmsSummary:"Pretoria and Wonderboom: no Pretoria rooms. Pretoria pilots take the N1 south to the New Road exit, or Gautrain (Hatfield, Pretoria, Centurion) to Midrand station, for Class 2 and Class 4 at Grand Central Airport. Wonderboom students need Class 2 and an SPL before solo (61.02.1). Class 1 needs a Senior DAME."},{path:"/aviation-medicals/centurion/",kind:"area",group:"Areas",navLabel:"Centurion",title:"Aviation Medical Centurion | Class 2 and 4 | ClinoTrend",description:"Centurion pilots and cabin crew: SACAA Class 2 and Class 4 aviation medicals at Grand Central Airport, Midrand, one Gautrain stop or the N1. From R1,500.",h1:"Aviation medical for Centurion pilots and cabin crew",eyebrow:"Centurion",trailName:"Centurion",lead:"Centurion sits between Pretoria and Midrand, so Grand Central Airport is close by road or rail. ClinoTrend has no Centurion rooms; Centurion pilots, students and cabin crew are seen at the Midrand terminal.",answer:"ClinoTrend has no Centurion rooms. Centurion pilots and cabin crew come to Grand Central Airport in Midrand, by the N1 south or the R101, or one Gautrain stop from Centurion to Midrand station, for Class 2 and Class 4 medicals with Dr A.O. Ndhlovu (SACAA Regular DAME, MR 336).",facts:["Usual roads: N1 south to the New Road exit, or the R101 south through Olifantsfontein.","Gautrain: Centurion station to Midrand station is one stop, then e-hailing or a taxi.",s],body:[{t:"h2",x:"From Centurion to Grand Central",id:"drive"},{t:"p",x:"Most Centurion drivers take the N1 south to the New Road exit. The R101, the old Pretoria road, runs south through Olifantsfontein into Midrand and is an alternative when the N1 is busy. From Irene, Eldoraigne or Rooihuiskraal, follow a live map onto either road. We do not publish journey times, because traffic changes them."},{t:"h2",x:"One Gautrain stop",id:"gautrain"},{t:"p",x:"Centurion station is the stop before Midrand on the Gautrain north-south line. From Midrand station, use e-hailing or a taxi to Grand Central Airport, 3 New Road. It suits a student without a car, or anyone avoiding N1 traffic."},{t:"h2",x:"Who books from Centurion",id:"who"},{t:"ul",items:["Students starting at a Grand Central, Wonderboom or Lanseria school, for a first [Class 2](/aviation-medicals/class-2/) and the [student pilot steps](/aviation-medicals/student-pilot/).","Private pilots, for a [Class 2 renewal](/aviation-medicals/renewal/) before the date on their certificate.","Cabin crew, for a [cabin crew medical](/aviation-medicals/class-4-cabin-crew/), Class 4 or Class 2 as the operator asks.","Recreational pilots, for a [Class 4](/aviation-medicals/recreational-pilots/)."]},{t:"p",x:g},{t:"h2",x:"On the day",id:"day"},{t:"p",x:`Complete the [SACAA application form online](/sacaa-form/) before you come. Dr Ndhlovu takes your medical history and examines you, and ${R} are done on site. The doctor tells you if a chest X-ray is needed. If you meet the SACAA standards and no further reports are needed, the certificate is issued at the end of the examination.`},{t:"p",x:`${v} Hours are ${A}, by appointment only.`},{t:"cta",x:"Book your medical from Centurion"}],airfields:[t.fagc,t.fawb,t.fala],bookService:null,bookLabel:"Book an aviation medical",related:["/aviation-medicals/gauteng/","/aviation-medicals/pretoria/","/aviation-medicals/midrand/","/aviation-medicals/class-2/","/aviation-medicals/renewal/","/aviation-medicals/cost/"],guides:["renew-sacaa-class-2-medical","class-2-medical-validity-by-age","sacaa-medical-classes-explained"],faqs:[{q:"Is there an aviation medical clinic in Centurion?",a:"ClinoTrend has no Centurion rooms. Centurion patients are seen at Grand Central Airport in Midrand, by the N1 south, the R101 or one Gautrain stop to Midrand station."},{q:"Can I take the Gautrain from Centurion to my medical?",a:"Yes. Ride one stop from Centurion to Midrand station, then use e-hailing or a taxi to Grand Central Airport, 3 New Road."},{q:"Is the certificate issued on the day?",a:"If you meet the SACAA standards and no further reports are needed, yes, at the end of the examination. If more reports are needed, it follows once they are in."},{q:"Do I need to fast before the medical?",a:"You do not need to fast. Rest well, and avoid caffeine, tobacco and high sugar meals beforehand, as they can affect urine and ECG results."}],areaServed:["Centurion","Irene","Olifantsfontein"],keyword:"aviation medical centurion",secondary:["aviation medical examiner centurion","pilot medical centurion"],sources:[i.register,i.issuing,i.classesReg],llmsSummary:"Centurion: no Centurion rooms. Centurion pilots and cabin crew go to Grand Central Airport, Midrand: N1 south to the New Road exit or the R101 through Olifantsfontein, or one Gautrain stop to Midrand station. Class 2 and Class 4, on-site ECG, vision, hearing and urine tests, from R1,500."},{path:"/aviation-medicals/east-rand/",kind:"area",group:"Areas",navLabel:"East Rand and Kempton Park",title:"Aviation Medical Kempton Park and East Rand | ClinoTrend",description:"Kempton Park, Benoni and Germiston cabin crew and pilots: SACAA Class 4 and Class 2 medicals at Grand Central Airport, Midrand, by R21, R562 or Gautrain.",h1:"Aviation medical for Kempton Park and East Rand crew and pilots",eyebrow:"Kempton Park, Benoni, Germiston",trailName:"East Rand",lead:"Kempton Park, Benoni and Germiston are home to many O.R. Tambo cabin crew and to pilots who fly from Rand Airport and Brakpan. ClinoTrend has no East Rand rooms. East Rand crew and pilots are seen at Grand Central Airport in Midrand.",answer:"ClinoTrend has no East Rand rooms. Cabin crew and pilots from Kempton Park, Benoni and Germiston come to Grand Central Airport in Midrand, by the R21 and R562, by the N3 and N1, or by Gautrain from O.R. Tambo via Marlboro, for Class 4 and Class 2 medicals with Dr A.O. Ndhlovu (SACAA Regular DAME, MR 336).",facts:["Cabin crew: Class 4 or Class 2, whichever the airline or operator asks for.","Gautrain: O.R. Tambo or Rhodesfield to Marlboro, change for Midrand station.",s],body:[{t:"h2",x:"Cabin crew medicals for O.R. Tambo crew",id:"crew"},{t:"p",x:"Cabin crew need a medical certificate under Part 64 (regulation 64.01.6). Amended Part 67 lists the cabin crew licence under Class 4, while some SACAA pages still show Class 2. Dr Ndhlovu issues either. Book the class your airline or operator asks for. The [cabin crew medical page](/aviation-medicals/class-4-cabin-crew/) covers validity and what the examination includes."},{t:"p",x:"Cabin crew academies and operators can arrange group bookings in advance. Call 011 568 7979 or email info@clinotrend-health.co.za with the number of people and the dates that suit you."},{t:"h2",x:"Rand Airport and Brakpan pilots",id:"pilots"},{t:"p",x:"Rand Airport (FAGM) in Germiston and Brakpan airfield (FABB) both have flight training. The [Brakpan Aero Club](https://brakpanaeroclub.co.za/flight-schools/) lists the schools at Brakpan. Students from these fields book a first [Class 2](/aviation-medicals/class-2/) before solo, and private pilots renew their Class 2 here. Microlight and other recreational pilots book a [Class 4](/aviation-medicals/recreational-pilots/)."},{t:"h2",x:"Getting to Grand Central from the East Rand",id:"routes"},{t:"table",caption:"Usual roads from the East Rand to Grand Central Airport, Midrand",head:["Coming from","Usual way"],rows:[["Kempton Park","R21 north, then the R562 west toward Midrand and New Road"],["Benoni, Boksburg, Brakpan","R21 north or the N12 to the R21, then the R562 west"],["Germiston, Bedfordview","N3 north to the N1 at Buccleuch, then the N1 north to the New Road or Allandale exit"],["O.R. Tambo crew without a car","Gautrain from O.R. Tambo or Rhodesfield to Marlboro, change to the north-south line for Midrand station, then e-hailing or a taxi"]]},{t:"p",x:"These are general routes. Traffic on the R21, R562 and N3 changes through the day, so check a live map and leave a margin. We do not publish journey times."},{t:"h2",x:"Fees and booking",id:"book"},{t:"p",x:`${s} ${d}`},{t:"cta",x:"Book a cabin crew or pilot medical"}],airfields:[t.faor,t.fagm,t.fabb,t.fagc],bookService:"class-4",bookLabel:"Book a Class 4 medical",related:["/aviation-medicals/gauteng/","/aviation-medicals/class-4-cabin-crew/","/aviation-medicals/johannesburg/","/aviation-medicals/recreational-pilots/","/aviation-medicals/class-2/","/aviation-medicals/cost/"],guides:["cabin-crew-medical-class-4-south-africa","sacaa-medical-classes-explained","student-pilot-medical-south-africa"],faqs:[{q:"Is there a ClinoTrend clinic in Kempton Park or at O.R. Tambo?",a:`No. The only clinic is at ${p}. Kempton Park patients usually take the R21 and R562, or the Gautrain via Marlboro to Midrand station.`},{q:"Which class do O.R. Tambo cabin crew need?",a:"Amended Part 67 lists cabin crew under Class 4, while some SACAA pages still show Class 2. Book the class your airline or operator asks for. Dr Ndhlovu issues either."},{q:"Can a cabin crew academy book a group?",a:f},{q:"I train at Rand Airport. Do I need a Class 2 or a Class 4?",a:"Student and private pilot licences for aeroplanes and helicopters need Class 2. Recreational licences such as microlight and gyroplane use Class 4. Your school can confirm which licence you are training for."}],areaServed:["Kempton Park","Benoni","Germiston","Boksburg","Brakpan","Edenvale"],keyword:"aviation medical kempton park",secondary:["cabin crew medical kempton park","aviation medical east rand","aviation medical benoni","rand airport medical"],sources:[i.cabin,i.classes,i.register,y.brakpan],llmsSummary:"Kempton Park and East Rand: no East Rand rooms. O.R. Tambo cabin crew and Rand Airport and Brakpan pilots go to Grand Central Airport, Midrand, by the R21 and R562, the N3 and N1, or Gautrain via Marlboro to Midrand station. Cabin crew get Class 4 or Class 2 as the operator asks. Group bookings arranged in advance."},{path:"/aviation-medicals/lanseria/",kind:"area",group:"Areas",navLabel:"Lanseria",title:"Aviation Medical for Lanseria Pilots | Class 2 | ClinoTrend",description:"Lanseria student and private pilots: SACAA Class 2 medicals at Grand Central Airport, Midrand, via the N14 and N1. First medicals and renewals from R1,500.",h1:"Aviation medical for Lanseria student and private pilots",eyebrow:"Lanseria and the north-west",trailName:"Lanseria",lead:"Lanseria International Airport has resident flying schools, and every student there needs a Class 2 medical before solo. ClinoTrend has no Lanseria rooms. Lanseria pilots are seen at Grand Central Airport in Midrand.",answer:"ClinoTrend has no Lanseria rooms. Lanseria students and private pilots come to Grand Central Airport in Midrand, usually by the N14 east and the N1 south, for Class 2 medicals with Dr A.O. Ndhlovu (SACAA Regular DAME, MR 336). First medicals and renewals start from R1,500.",facts:["Students need a Class 2 and an SPL before the first solo flight.","Usual road: N14 east toward Centurion, then the N1 south to Midrand.","Pilots with a valid certificate can fly in to FAGC."],body:[{t:"h2",x:"Lanseria flight schools and the Class 2",id:"schools"},{t:"p",x:"Lanseria lists its resident flying schools on its [own website](https://lanseria.co.za/corporate/pilot-and-aviation-info/flying-schools/), including Aeronav Academy and Cirrus Certified Training (checked 10 November 2026). Students from any school book a first [Class 2 medical](/aviation-medicals/class-2/) at ClinoTrend."},{t:"p",x:"Under amended Part 61 (regulation 61.02.1), a Student Pilot Licence applicant must be at least 15, hold a valid medical certificate and be registered with an approved training organisation. Book the medical before you plan the first solo. The [student pilot medical page](/aviation-medicals/student-pilot/) has the full order of steps."},{t:"h2",x:"By road from Lanseria",id:"drive"},{t:"p",x:"The usual road is the N14 east toward Centurion, then the N1 south to the New Road exit in Midrand. From Fourways and Diepsloot, a live map may suggest local roads east. We do not publish journey times."},{t:"h2",x:"Flying in from Lanseria",id:"fly"},{t:"p",x:"Pilots with a current certificate can fly to Grand Central (FAGC) and park on the apron outside the Gate 2 terminal doors. The clinic is inside the same terminal. Check current procedures, NOTAMs and fees with the airport before you plan the flight. See [flying in for a medical](/aviation-medicals/fly-in/)."},{t:"h2",x:"Renewing at Grand Central",id:"renew"},{t:"p",x:"Under 40, a Class 2 is valid for 60 months. From 40 to 49 it is valid for 24 months, and from 50 it is valid for 12 months. Book a few weeks before your expiry date. The [renewal page](/aviation-medicals/renewal/) has an expiry calculator."},{t:"p",x:s},{t:"cta",x:"Book a Class 2 medical"}],airfields:[t.fala,t.fagc],bookService:"class-2",bookLabel:"Book a Class 2 medical",related:["/aviation-medicals/gauteng/","/aviation-medicals/student-pilot/","/aviation-medicals/class-2/","/aviation-medicals/fly-in/","/aviation-medicals/johannesburg/","/aviation-medicals/renewal/"],guides:["student-pilot-medical-south-africa","class-2-medical-validity-by-age","renew-sacaa-class-2-medical"],faqs:[{q:"Is there a ClinoTrend clinic at Lanseria?",a:"No. Lanseria pilots are seen at Grand Central Airport in Midrand, usually by the N14 east and the N1 south, or by flying in to FAGC."},{q:"Can I do my Class 2 before I sign up with a Lanseria school?",a:"Yes. You can do the medical first, so you know where you stand before paying for training. You need the medical before you can be issued a Student Pilot Licence."},{q:"Can I fly in to Grand Central for my renewal?",a:"Yes, if your current certificate is still valid. Park on the apron outside the Gate 2 terminal doors. Check current airport procedures, NOTAMs and fees before you fly."},{q:"How long is a Class 2 valid?",a:"60 months under 40, 24 months from 40 to 49, and 12 months from 50, running to the last day of a month."}],areaServed:["Lanseria","Fourways","Diepsloot","Muldersdrift"],keyword:"aviation medical lanseria",secondary:["class 2 medical lanseria","lanseria flight school medical"],sources:[y.lanseriaSchools,i.spl,i.validityReg,i.register],llmsSummary:"Lanseria: no Lanseria rooms. Lanseria students and private pilots get Class 2 medicals at Grand Central Airport, Midrand, by the N14 and N1, or by flying in to FAGC with a valid certificate. SPL needs age 15, a medical and ATO registration (61.02.1). Class 2 valid 60, 24 or 12 months by age."},{path:"/aviation-medicals/fly-in/",kind:"area",group:"Areas",navLabel:"Fly in from outside Gauteng",title:"Fly-In Aviation Medical | Grand Central FAGC | ClinoTrend",description:"Flying in from Limpopo, Mpumalanga, North West or the Free State? Book a SACAA Class 2 or Class 4 at Grand Central Airport and park by the terminal doors.",h1:"Fly in for your aviation medical at Grand Central Airport",eyebrow:"Pilots from outside Gauteng",trailName:"Fly in",lead:"Pilots from Limpopo, Mpumalanga, North West and the Free State fly in to Grand Central (FAGC) for a medical, because the clinic is inside the terminal. Visitor aircraft park on the apron right outside the Gate 2 doors.",answer:"ClinoTrend is inside the main terminal at Grand Central Airport (FAGC), Midrand. Pilots flying in from outside Gauteng park on the apron outside the Gate 2 terminal doors and walk in for a Class 2 or Class 4 medical with Dr A.O. Ndhlovu (SACAA Regular DAME, MR 336). Book first. Your current certificate must be valid for the flight.",facts:["The apron and visitor aircraft parking are directly outside the Gate 2 terminal doors.","Book before you fly: medicals are by appointment only.","If your certificate has expired, come by road or with another pilot."],body:[{t:"h2",x:"Why pilots fly in for a medical",id:"why"},{t:"p",x:"For a pilot outside Gauteng, a medical at an airport means the trip is a flight, with no drive into town at the other end. At Grand Central the apron and visitor aircraft parking are directly outside the Gate 2 terminal doors, and ClinoTrend is inside the same building: through the main entrance, first right, straight ahead."},{t:"h2",x:"Plan around your expiry date",id:"expiry"},{t:"p",x:"You need a valid medical certificate to fly as pilot in command. Book the medical while your current certificate is still valid, so you can fly in and out. If it has already expired, travel by road or with another pilot."},{t:"p",x:"If you cannot be examined before expiry, regulation 67.00.6(6) lets you apply for an extension at least 15 days before the expiry date. An extension lasts no more than 30 days. The [renewal page](/aviation-medicals/renewal/) has an expiry calculator."},{t:"h2",x:"Before you fly",id:"plan"},{t:"ul",items:["[Book your medical](/book/) and tell us you are flying in, so your time suits your flight.","Check current procedures, NOTAMs, landing and parking fees with Grand Central Airport before you plan the flight.","Complete the [SACAA application form online](/sacaa-form/) before the day.","Avoid caffeine, tobacco and high sugar meals before the medical, as they can affect urine and ECG results.","Leave time for weather. If you need to move the appointment, give at least 24 hours notice."]},{t:"h2",x:"Which provinces pilots fly in from",id:"provinces"},{t:"p",x:"Pilots based in Limpopo (Polokwane and the bushveld fields), Mpumalanga (Mbombela, Nelspruit and the Lowveld), North West (Rustenburg and Brits) and the Free State (Bloemfontein and the farm strips) can fly in to Grand Central for a medical. ClinoTrend has no rooms in those provinces. We list them here so you know a fly-in medical is an option, not because there is a local clinic."},{t:"h2",x:"What is done at the medical",id:"day"},{t:"p",x:`Dr Ndhlovu takes your medical history and examines you. ${h} are done on site, and the doctor tells you if a chest X-ray is needed. If you meet the SACAA standards and no further reports are needed, the certificate is issued at the end of the examination. ${s}`},{t:"p",x:g},{t:"cta",x:"Book a fly-in medical"}],airfields:[t.fagc],bookService:"renewal",bookLabel:"Book a renewal",related:["/aviation-medicals/gauteng/","/aviation-medicals/renewal/","/aviation-medicals/class-2/","/aviation-medicals/recreational-pilots/","/aviation-medicals/lanseria/","/aviation-medicals/midrand/"],guides:["renew-sacaa-class-2-medical","class-2-medical-validity-by-age","aviation-medical-deferred-what-next"],faqs:[{q:"Where do I park my aircraft for the medical?",a:"The apron and visitor aircraft parking are directly outside the Gate 2 terminal doors at Grand Central. ClinoTrend is inside the main terminal. Check current procedures and fees with the airport before you fly."},{q:"Can I fly in if my medical has expired?",a:"No. You need a valid medical certificate to fly as pilot in command. Book while your certificate is valid, or come by road or with another pilot."},{q:"Is there a ClinoTrend clinic in Polokwane, Mbombela, Rustenburg or Bloemfontein?",a:"No. The only clinic is at Grand Central Airport in Midrand. Pilots from those areas fly in or drive."},{q:"What if the weather stops me flying in?",a:"Contact the practice as soon as you can to move the appointment. We ask for at least 24 hours notice where possible."}],areaServed:["Limpopo","Mpumalanga","North West","Free State","Polokwane","Mbombela","Rustenburg","Bloemfontein"],keyword:"fly in aviation medical",secondary:["aviation medical polokwane","aviation medical nelspruit","aviation medical bloemfontein","aviation medical rustenburg"],sources:[i.validityReg,i.register,i.am007],llmsSummary:"Fly-in: pilots from Limpopo, Mpumalanga, North West and the Free State fly in to Grand Central (FAGC). Visitor aircraft park on the apron outside the Gate 2 terminal doors, and the clinic is inside the terminal. Book while your certificate is valid; extensions under 67.00.6(6) last no more than 30 days. No clinics outside Midrand."},{path:"/aviation-medicals/class-2/",kind:"service",group:"Medicals",navLabel:"Class 2 medical",title:"SACAA Class 2 Medical Gauteng | PPL and SPL | ClinoTrend",description:"SACAA Class 2 aviation medical for student and private pilots at Grand Central Airport, Midrand: who needs it, validity by age, on-site tests. From R1,500.",h1:"SACAA Class 2 medical for student and private pilots",eyebrow:"Class 2 medical",trailName:"Class 2 medical",lead:"The Class 2 is the medical for the Student Pilot Licence and the Private Pilot Licence. Dr A.O. Ndhlovu does first Class 2 medicals and renewals at Grand Central Airport in Midrand.",answer:"A Class 2 medical is required for the Student Pilot Licence (SPL) and the Private Pilot Licence (PPL) for aeroplanes, helicopters and airships, among others, under Part 67 regulation 67.00.2. It is valid for 60 months under 40, 24 months from 40 and 12 months from 50. At ClinoTrend it costs from R1,500.",facts:["Issued by a SACAA Regular or Senior DAME. Dr A.O. Ndhlovu is Regular DAME MR 336.",`${h} are done on site.`,"If you meet the standards and no reports are pending, the certificate is issued at the end of the examination."],body:[{t:"h2",x:"Who needs a Class 2 medical",id:"who"},{t:"p",x:"Regulation 67.00.2 lists the licences that need a Class 2. The main ones are:"},{t:"ul",items:["Student Pilot Licence (SPL), before the first solo flight","Private Pilot Licence (PPL) for aeroplanes, helicopters and airships","Flight engineer licence","Commercial glider and commercial free balloon licences"]},{t:"p",x:"A Class 1 holder is deemed to hold a Class 2, so a commercial pilot does not need both. Recreational licences such as microlight and gyroplane use [Class 4](/aviation-medicals/recreational-pilots/). The [guide to SACAA medical classes](/blog/sacaa-medical-classes-explained/) has the full list."},{t:"h2",x:"How long a Class 2 is valid",id:"validity"},{t:"table",caption:"Class 2 validity under regulation 67.00.6(3)",head:["Your age","Valid for"],rows:[["Under 40","60 months"],["From your 40th birthday","24 months"],["From your 50th birthday","12 months"]]},{t:"p",x:"The period runs to the last day of a month. A medical condition can mean a shorter period, and the date on your certificate is the one that applies. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) explains how the date is counted."},{t:"h2",x:"What happens at a Class 2 medical",id:"day"},{t:"ol",items:["[Book online](/book/?service=class-2) and complete the [SACAA application form online](/sacaa-form/).",`Dr Ndhlovu takes your medical history on the [Aviation Medical Report, CA 67-02(a)](${G}), and examines you.`,`${h} are done on site. The doctor tells you if a chest X-ray is needed.`,"If you meet the SACAA standards and no further reports are needed, the certificate is issued at the end of the examination.","If more information is needed, the assessment is deferred until it arrives. See [what happens if your medical is deferred](/blog/aviation-medical-deferred-what-next/)."]},{t:"h2",x:"First Class 2 or renewal",id:"first"},{t:"p",x:"A first Class 2 is usually part of starting flight training. See the [student pilot medical](/aviation-medicals/student-pilot/) page for the order of steps. For a renewal, book a few weeks before the date on your certificate. The [renewal page](/aviation-medicals/renewal/) has an expiry calculator and the extension rules."},{t:"h2",x:"What to bring",id:"bring"},{t:"ul",items:b},{t:"p",x:"Rest well, and avoid caffeine, tobacco and high sugar meals beforehand, as they can affect urine and ECG results."},{t:"h2",x:"Fee",id:"fee"},{t:"p",x:`${s} ${d} See the [aviation medical cost page](/aviation-medicals/cost/).`},{t:"cta",x:"Book a Class 2 medical"}],airfields:[],bookService:"class-2",bookLabel:"Book a Class 2 medical",related:["/aviation-medicals/student-pilot/","/aviation-medicals/renewal/","/aviation-medicals/cost/","/aviation-medicals/gauteng/","/aviation-medicals/midrand/","/aviation-medicals/fly-in/"],guides:["class-2-medical-validity-by-age","renew-sacaa-class-2-medical","sacaa-medical-classes-explained","aviation-medical-deferred-what-next"],faqs:[{q:"Do I need a Class 2 for a PPL in South Africa?",a:"Yes. Regulation 67.00.2 lists the Private Pilot Licence for aeroplanes, helicopters and airships under Class 2. A Class 1 holder is deemed to hold a Class 2."},{q:"How long is a Class 2 valid if I am under 40?",a:"60 months, running to the last day of a month, under regulation 67.00.6(3). From your 40th birthday it is 24 months, and from your 50th birthday 12 months."},{q:"Can a Class 2 be done by any doctor?",a:"No. A Class 2 must be done by a SACAA designated examiner, either a Regular or a Senior DAME. Only Class 4 may also be done by a registered medical practitioner under regulation 67.00.5."},{q:"Is the Class 2 medical done on the same day?",a:"Most aviation medicals are completed on the same day, depending on your case. If you meet the standards and no further reports are needed, the certificate is issued at the end of the examination."},{q:"How much is a Class 2 medical?",a:s}],areaServed:["Gauteng","Midrand","Johannesburg","Pretoria"],keyword:"class 2 medical",secondary:["sacaa class 2 medical","class 2 medical certificate south africa","ppl medical south africa","private pilot medical"],sources:[i.classes,i.classesReg,i.validityReg,i.form,i.register],llmsSummary:"Class 2: for SPL, PPL (aeroplane, helicopter, airship), flight engineer, commercial glider and commercial balloon (67.00.2). Valid 60 months under 40, 24 from 40, 12 from 50 (67.00.6(3)). Done by a Regular or Senior DAME; Dr A.O. Ndhlovu (MR 336) at Grand Central Airport, Midrand. On-site ECG, vision, hearing, urine. From R1,500."},{path:"/aviation-medicals/class-4-cabin-crew/",kind:"service",group:"Medicals",navLabel:"Cabin crew medical",title:"Cabin Crew Medical Gauteng | Class 4 SACAA | ClinoTrend",description:"Cabin crew medical in Gauteng: SACAA Class 4 or Class 2, as your airline asks, at Grand Central Airport, Midrand. Validity, yearly declaration, groups.",h1:"Cabin crew medical: SACAA Class 4 or Class 2",eyebrow:"Cabin crew medical",trailName:"Cabin crew medical",lead:"Cabin crew need a medical certificate before they fly. Dr A.O. Ndhlovu issues the cabin crew medical as Class 4 or Class 2, whichever your airline, operator or academy asks for, at Grand Central Airport in Midrand.",answer:"Cabin crew need a SACAA medical certificate under Part 64. Amended Part 67 lists the cabin crew licence under Class 4, while some SACAA pages still show Class 2. ClinoTrend issues either at Grand Central Airport, Midrand. A Class 4 is valid for 60 months under 40 and 36 months from 40. Fees start from R1,500.",facts:["Book the class your airline, operator or academy asks for.","Class 4 holders submit a yearly medical declaration to SACAA (67.00.9(3)).","Academy and airline groups are arranged in advance."],body:[{t:"h2",x:"Class 4 or Class 2 for cabin crew?",id:"which"},{t:"p",x:"Regulation 64.01.6 requires cabin crew to hold a medical certificate. Amended Part 67 (regulation 67.00.2) lists the cabin crew member licence under Class 4. Some SACAA pages and some operators still refer to Class 2. Dr Ndhlovu issues both, so book the class your airline, operator or academy asks for. If you are unsure, ask them before you book."},{t:"h2",x:"Validity",id:"validity"},{t:"table",caption:"Validity for cabin crew certificates under regulation 67.00.6",head:["Certificate","Under 40","From 40","From 50"],rows:[["Class 4","60 months","36 months","36 months"],["Class 2","60 months","24 months","12 months"]]},{t:"p",x:"Periods run to the last day of a month, and a medical condition can mean a shorter period. The [cabin crew medical guide](/blog/cabin-crew-medical-class-4-south-africa/) has the detail."},{t:"h2",x:"The yearly Class 4 declaration",id:"declaration"},{t:"p",x:"If you hold a Class 4, regulation 67.00.9(3) requires you to complete and submit a medical declaration to SACAA every year, on the form prescribed in SA-CATS 67. Contact the practice or SACAA if you are unsure which form to use."},{t:"h2",x:"What the medical includes",id:"day"},{t:"p",x:`Dr Ndhlovu takes your medical history on the SACAA form CA 67-02(a) and examines you. ${h} are done on site, and the doctor tells you if a chest X-ray is needed. If you meet the standards and no further reports are needed, the certificate is issued at the end of the examination.`},{t:"h2",x:"Who may do a Class 4",id:"gp"},{t:"p",x:"A Class 4 is the one class that does not have to be done by a designated examiner. Regulation 67.00.5 allows any medical practitioner registered with the HPCSA to do it, provided the results are sent for verification within 60 days. A Class 2 must be done by a DAME. At ClinoTrend, both are done by a SACAA Regular DAME."},{t:"h2",x:"Academies, airlines and groups",id:"groups"},{t:"p",x:`${f} Crew who live on the East Rand can see [routes from Kempton Park and Benoni](/aviation-medicals/east-rand/).`},{t:"h2",x:"What to bring and the fee",id:"bring"},{t:"ul",items:b},{t:"p",x:`${s} ${d}`},{t:"cta",x:"Book a cabin crew medical"}],airfields:[t.faor,t.fagc],bookService:"class-4",bookLabel:"Book a Class 4 medical",related:["/aviation-medicals/east-rand/","/aviation-medicals/recreational-pilots/","/aviation-medicals/class-2/","/aviation-medicals/cost/","/aviation-medicals/gauteng/","/aviation-medicals/johannesburg/"],guides:["cabin-crew-medical-class-4-south-africa","sacaa-medical-classes-explained","class-2-medical-validity-by-age"],faqs:[{q:"Which class of medical do cabin crew need in South Africa?",a:"Amended Part 67 lists the cabin crew licence under Class 4, while some SACAA pages still show Class 2. Book the class your airline or operator asks for. ClinoTrend issues either."},{q:"How long is a cabin crew Class 4 valid?",a:"60 months if you are under 40, and 36 months from 40, under regulation 67.00.6(4), to the last day of a month."},{q:"Do I have to send anything to SACAA between medicals?",a:"If you hold a Class 4, yes. Regulation 67.00.9(3) requires a yearly medical declaration on the form prescribed in SA-CATS 67."},{q:"Can a cabin crew academy book a whole intake?",a:f}],areaServed:["Gauteng","Kempton Park","Johannesburg","Midrand"],keyword:"cabin crew medical",secondary:["class 4 medical","cabin crew medical gauteng","class 4 medical south africa","flight attendant medical"],sources:[i.cabin,i.classes,i.class4,i.validityReg,i.duties],llmsSummary:"Cabin crew: medical required by 64.01.6. Amended Part 67 lists cabin crew under Class 4; some SACAA pages still show Class 2. ClinoTrend issues either. Class 4 valid 60 months under 40, 36 from 40 (67.00.6(4)), yearly declaration (67.00.9(3)). Group bookings for academies and airlines arranged in advance. From R1,500."},{path:"/aviation-medicals/renewal/",kind:"service",group:"Medicals",navLabel:"Medical renewal",title:"Aviation Medical Renewal Gauteng | Class 2 | ClinoTrend",description:"Renew your SACAA Class 2 or Class 4 medical at Grand Central Airport, Midrand: when to book, expiry calculator, the 30 day extension rule, what to bring.",h1:"Renew your SACAA aviation medical before it expires",eyebrow:"Medical renewal",trailName:"Renewal",lead:"Check the date on your certificate, then book a few weeks before it. That leaves time for any extra report, so you are not grounded while you wait. Use the calculator below to work out your date.",answer:"Book your renewal a few weeks before the expiry date on your current certificate. If you meet the SACAA standards and no further reports are needed, the new certificate is issued at the end of the examination. If you cannot be examined in time, apply to SACAA for an extension at least 15 days before expiry; an extension lasts no more than 30 days.",facts:["Class 2: 60 months under 40, 24 months from 40, 12 months from 50.","Class 4: 60 months under 40, 36 months from 40.","Bring your current certificate, licence and logbook."],body:[{t:"h2",x:"Work out your expiry date",id:"calculator"},{t:"p",x:"Enter your date of birth and the date of your last medical. The calculator applies the periods in regulation 67.00.6. The date printed on your certificate is the one that applies."},{t:"calc"},{t:"h2",x:"When to book",id:"when"},{t:"p",x:"Book a few weeks before your expiry date. If the doctor needs a report from your own doctor or a specialist, the assessment is deferred until it arrives, and that takes time. See [what happens if your medical is deferred](/blog/aviation-medical-deferred-what-next/)."},{t:"h2",x:"If you are running out of time",id:"extension"},{t:"p",x:"Regulation 67.00.6(6) says you must apply for an extension at least 15 days before your certificate expires, and the Director may extend it, on conditions, for no more than 30 days. SACAA procedure AM007 also says to contact the SACAA medical department before the expiry date. The [Class 2 renewal guide](/blog/renew-sacaa-class-2-medical/) covers the steps."},{t:"h2",x:"What happens at a renewal",id:"day"},{t:"p",x:`A renewal follows the same steps as a first medical. Complete the [SACAA application form online](/sacaa-form/). Dr Ndhlovu takes your medical history, including anything new since your last medical, and examines you. ${h} are done on site. If you meet the standards and no further reports are needed, the certificate is issued at the end of the examination.`},{t:"p",x:"Under SACAA procedure AM007, the certificate is issued in two copies with the same serial number. The yellow copy goes to the SACAA licensing department and you keep the white copy."},{t:"h2",x:"Bring these to your renewal",id:"bring"},{t:"ul",items:b},{t:"h2",x:"Fee and booking",id:"fee"},{t:"p",x:`${s} ${d} Pilots outside Gauteng can [fly in to Grand Central](/aviation-medicals/fly-in/) while their certificate is still valid.`},{t:"cta",x:"Book your renewal"}],airfields:[t.fagc],bookService:"renewal",bookLabel:"Book a renewal",related:["/aviation-medicals/class-2/","/aviation-medicals/fly-in/","/aviation-medicals/cost/","/aviation-medicals/class-4-cabin-crew/","/aviation-medicals/gauteng/","/aviation-medicals/pretoria/"],guides:["renew-sacaa-class-2-medical","class-2-medical-validity-by-age","aviation-medical-deferred-what-next"],faqs:[{q:"How early can I renew my aviation medical?",a:"Book a few weeks before the expiry date on your current certificate. That leaves time for any extra report. The new certificate runs from the new examination."},{q:"What if my medical expires before I can be examined?",a:"Contact the SACAA medical department before the expiry date, as AM007 requires. Regulation 67.00.6(6) says to apply at least 15 days before expiry, and an extension is for no more than 30 days."},{q:"Do I need to bring my logbook to a renewal?",a:"Yes, bring your logbook with your ID, licence, current certificate and a list of every medicine you take."},{q:"Can I renew at a different examiner from last time?",a:"Yes. Any SACAA DAME who may issue your class can do your renewal. Dr A.O. Ndhlovu is Regular DAME MR 336 and issues Class 2 and Class 4."}],areaServed:["Gauteng","Midrand","Johannesburg","Pretoria","Centurion"],keyword:"aviation medical renewal",secondary:["renew class 2 medical","sacaa medical renewal","sacaa medical extension","class 2 medical expired"],sources:[i.validityReg,i.am007,i.application,i.register],llmsSummary:"Renewal: book a few weeks before the expiry date. Expiry calculator on the page. Extension under 67.00.6(6): apply at least 15 days before expiry, no more than 30 days; AM007 says contact SACAA before expiry. Certificate issued at the end of the examination if no reports are needed. From R1,500."},{path:"/aviation-medicals/student-pilot/",kind:"service",group:"Medicals",navLabel:"Student pilot medical",title:"Student Pilot Medical South Africa | Class 2 | ClinoTrend",description:"Student pilot medical in Gauteng: the Class 2 you need for an SPL, the age and training rules in Part 61, and how to book at Grand Central Airport, Midrand.",h1:"Student pilot medical: your first Class 2",eyebrow:"Student pilot medical",trailName:"Student pilot",lead:"Every student pilot needs a medical certificate before a Student Pilot Licence can be issued. For aeroplane and helicopter students that is a Class 2, done by a SACAA designated examiner.",answer:"A student pilot needs a Class 2 medical for the Student Pilot Licence. Under amended Part 61 (regulation 61.02.1), an SPL applicant must be at least 15, hold a valid medical certificate and be registered with an approved training organisation. Dr A.O. Ndhlovu (SACAA Regular DAME, MR 336) does first Class 2 medicals at Grand Central Airport, Midrand, from R1,500.",facts:["SPL: age 15 or older, a valid medical, ATO registration (61.02.1, amended 21 August 2026).","You can do the medical before you sign up with a school.","Recreational students (microlight, gyroplane) use Class 4."],body:[{t:"h2",x:"Steps to a Student Pilot Licence",id:"steps"},{t:"ol",items:["Choose an approved training organisation (ATO). Grand Central, Lanseria, Wonderboom, Rand Airport and Brakpan all have flight schools.","[Book a Class 2 medical](/book/?service=class-2) and complete the [SACAA application form online](/sacaa-form/).","Attend the medical. If you meet the standards and no further reports are needed, the certificate is issued at the end of the examination.","Register with the ATO and apply for the Student Pilot Licence once you are 15 or older."]},{t:"p",x:"The [student pilot medical guide](/blog/student-pilot-medical-south-africa/) explains each step in more detail."},{t:"h2",x:"Why do the medical first",id:"first"},{t:"p",x:"You can do the medical before you pay for training. If something needs a report from your own doctor or a specialist, you find out early, and you have time to sort it out before your first solo is planned."},{t:"h2",x:"What happens at a first Class 2",id:"day"},{t:"p",x:`Dr Ndhlovu takes your full medical history and examines you. ${h} are done on site, and the doctor tells you if a chest X-ray is needed. Rest well, and avoid caffeine, tobacco and high sugar meals beforehand, as they can affect urine and ECG results.`},{t:"h2",x:"Planning a commercial career",id:"career"},{t:"p",x:`A Class 2 covers the SPL and PPL stages. The CPL, ATPL and instrument rating need a Class 1 from a SACAA Senior DAME. ${g} See the [guide to SACAA medical classes](/blog/sacaa-medical-classes-explained/).`},{t:"h2",x:"Flight schools and groups",id:"groups"},{t:"p",x:`Students at schools on Grand Central, such as those in the [airport tenant directory](https://www.grandcentral.co.za/tenant-directory/), can book between lessons. ${f}`},{t:"h2",x:"What to bring and the fee",id:"bring"},{t:"ul",items:["Your South African ID or passport","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"]},{t:"p",x:`${s} ${d}`},{t:"cta",x:"Book your first Class 2"}],airfields:[t.fagc,t.fala,t.fawb,t.fagm,t.fabb],bookService:"class-2",bookLabel:"Book a Class 2 medical",related:["/aviation-medicals/class-2/","/aviation-medicals/lanseria/","/aviation-medicals/pretoria/","/aviation-medicals/midrand/","/aviation-medicals/recreational-pilots/","/aviation-medicals/cost/"],guides:["student-pilot-medical-south-africa","sacaa-medical-classes-explained","class-2-medical-validity-by-age"],faqs:[{q:"How old do I need to be for a Student Pilot Licence?",a:"At least 15, under amended Part 61 regulation 61.02.1. You also need a valid medical certificate and registration with an approved training organisation."},{q:"Which medical does a student pilot need?",a:"A Class 2 for aeroplane, helicopter and airship students. Students for recreational licences such as microlight and gyroplane need a Class 4."},{q:"Should I do the medical before paying for flight training?",a:"You can. Doing it first means any report your examiner needs is sorted out before your first solo is planned."},{q:"Do I need a Class 1 to start training for an airline career?",a:"Not to start. The SPL and PPL use Class 2. Class 1 is needed for the CPL, ATPL and instrument rating, from a SACAA Senior DAME."}],areaServed:["Gauteng","Midrand","Johannesburg","Pretoria","Lanseria"],keyword:"student pilot medical",secondary:["spl medical","student pilot licence requirements south africa","first class 2 medical"],sources:[i.spl,i.classesReg,i.register,y.gcDirectory],llmsSummary:"Student pilot: Class 2 for the SPL. SPL needs age 15, a valid medical and ATO registration (61.02.1, amended 21 August 2026). Do the medical before paying for training if you like. CPL, ATPL and instrument rating later need Class 1 from a Senior DAME. First Class 2 at Grand Central Airport, Midrand, from R1,500."},{path:"/aviation-medicals/recreational-pilots/",kind:"service",group:"Medicals",navLabel:"Recreational pilot medical",title:"Microlight and Recreational Pilot Medical | ClinoTrend",description:"Class 4 medical for microlight, gyroplane, light sport, glider and balloon pilots at Grand Central Airport, Midrand. Validity, declaration, from R1,500.",h1:"Class 4 medical for microlight and recreational pilots",eyebrow:"Recreational pilot medical",trailName:"Recreational pilots",lead:"Most recreational licences in South Africa use a Class 4 medical. Dr A.O. Ndhlovu issues Class 4 medicals for microlight, gyroplane, light sport, glider and balloon pilots at Grand Central Airport in Midrand.",answer:"Microlight, gyroplane, light sport aeroplane, non-commercial glider and non-commercial free balloon licences use a Class 4 medical under Part 67 regulation 67.00.2. A Class 4 is valid for 60 months under 40 and 36 months from 40, and the holder submits a yearly declaration. ClinoTrend issues Class 4 from R1,500.",facts:["Class 4 validity: 60 months under 40, 36 months from 40.","Yearly medical declaration to SACAA (67.00.9(3)).","Paragliding, hang gliding, powered paratrike and parachute licences use Class 5."],body:[{t:"h2",x:"Which recreational licences use Class 4",id:"which"},{t:"p",x:"The SACAA DAMEs guide and regulation 67.00.2 list these licences under Class 4:"},{t:"ul",items:["Microlight aeroplane pilot licence","Gyroplane pilot licence","Light sport aeroplane pilot licence","Non-commercial glider pilot licence","Non-commercial free balloon pilot licence","The student licences for these"]},{t:"p",x:"Commercial glider and commercial balloon licences use [Class 2](/aviation-medicals/class-2/). The [guide to SACAA medical classes](/blog/sacaa-medical-classes-explained/) has the full list."},{t:"h2",x:"Class 5 is different",id:"class5"},{t:"p",x:"Paragliding, hang gliding, powered paratrike and parachute licences, and their student licences, use Class 5. Under regulation 67.00.2(8), a person under 60 who submits a duly completed Class 5 medical self-declaration, on the prescribed form and signed by a medical practitioner registered under the Health Professions Act, is deemed to hold a Class 5 certificate. From age 60 the form is the medical declaration prescribed for that age, also signed by a registered medical practitioner."},{t:"h2",x:"Validity and the yearly declaration",id:"validity"},{t:"p",x:"Under regulation 67.00.6(4), a Class 4 is valid for 60 months if you are under 40, and 36 months from 40, to the last day of a month. Regulation 67.00.9(3) requires Class 4 holders to submit a medical declaration to SACAA every year, on the form prescribed in SA-CATS 67."},{t:"h2",x:"Who may do a Class 4",id:"who"},{t:"p",x:"Regulation 67.00.5 allows any medical practitioner registered with the HPCSA to do a Class 4, provided the results are sent for verification within 60 days. A SACAA DAME may also issue it. Dr A.O. Ndhlovu is Regular DAME MR 336."},{t:"h2",x:"What happens at the medical",id:"day"},{t:"p",x:`Complete the [SACAA application form online](/sacaa-form/). Dr Ndhlovu takes your medical history and examines you. ${h} are done on site. If you meet the standards and no further reports are needed, the certificate is issued at the end of the examination. Pilots with a valid certificate can [fly in to Grand Central](/aviation-medicals/fly-in/).`},{t:"p",x:`${s} ${d}`},{t:"cta",x:"Book a Class 4 medical"}],airfields:[t.fagc,t.fabb,t.fagm],bookService:"class-4",bookLabel:"Book a Class 4 medical",related:["/aviation-medicals/class-4-cabin-crew/","/aviation-medicals/class-2/","/aviation-medicals/fly-in/","/aviation-medicals/east-rand/","/aviation-medicals/cost/","/aviation-medicals/gauteng/"],guides:["sacaa-medical-classes-explained","class-2-medical-validity-by-age","sacaa-medical-examiners-dame"],faqs:[{q:"What medical do I need for a microlight licence?",a:"A Class 4, under Part 67 regulation 67.00.2. The same applies to gyroplane, light sport aeroplane, non-commercial glider and non-commercial free balloon licences."},{q:"How long is a Class 4 valid?",a:"60 months if you are under 40, and 36 months from 40, under regulation 67.00.6(4), to the last day of a month."},{q:"What medical do paragliders need?",a:"Class 5. Under 60, it is a Class 5 medical self-declaration on the prescribed form, signed by a medical practitioner registered under the Health Professions Act. From 60 the form is the medical declaration prescribed for that age."},{q:"Do I send SACAA anything between Class 4 medicals?",a:"Yes. Regulation 67.00.9(3) requires a yearly medical declaration on the form prescribed in SA-CATS 67."}],areaServed:["Gauteng","Midrand","Brakpan","Germiston"],keyword:"microlight medical",secondary:["class 4 medical","recreational pilot medical","gyroplane medical","glider pilot medical"],sources:[y.damesGuide,i.classes,i.class4,i.validityReg,i.duties],llmsSummary:"Recreational pilots: microlight, gyroplane, light sport, non-commercial glider and non-commercial balloon licences use Class 4 (67.00.2). Valid 60 months under 40, 36 from 40, yearly declaration. Paragliding, hang gliding, paratrike and parachute use Class 5 (a self-declaration signed by a registered medical practitioner under 60). Class 4 at Grand Central Airport, Midrand, from R1,500."},{path:"/aviation-medicals/cost/",kind:"service",group:"Medicals",navLabel:"Aviation medical cost",title:"Aviation Medical Cost | From R1,500 | ClinoTrend",description:"What an aviation medical costs at ClinoTrend, Grand Central Airport: from R1,500, what may add to it, payment, medical aid rates and group bookings explained.",h1:"How much does an aviation medical cost?",eyebrow:"Aviation medical cost",trailName:"Cost",lead:"An aviation medical at ClinoTrend starts from R1,500. This page explains what can change the fee, how to pay, and which costs are charged by SACAA rather than the practice.",answer:"At ClinoTrend, Grand Central Airport, aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and the fee is confirmed when you book. Payment is by EFT or card at the visit. Most medical aids are accepted at medical aid rates.",facts:["From R1,500, confirmed when you book.","EFT or card at the visit. Medical aid rates. Self-pay patients get a quote first.","SACAA licence fees are separate and paid to SACAA."],body:[{t:"h2",x:"What the fee covers",id:"covers"},{t:"p",x:`The fee covers the examination by Dr A.O. Ndhlovu (SACAA Regular DAME, MR 336) and the tests done on site: ${R}. If you meet the SACAA standards and no further reports are needed, the certificate is issued at the end of the examination.`},{t:"h2",x:"What can add to the cost",id:"extra"},{t:"p",x:"Extra tests or reports are added only if the doctor finds they are needed during the medical. For example, the doctor tells you if a chest X-ray is needed, and a medical condition may need a report from your own doctor or a specialist. Any such cost is discussed with you first. Self-pay patients receive a quote before treatment."},{t:"h2",x:"Payment and medical aid",id:"payment"},{t:"p",x:d},{t:"h2",x:"Costs charged by SACAA",id:"sacaa"},{t:"p",x:"Licence fees are charged by SACAA, not by the practice. They are set out in the [SACAA fees, charges and levies](https://www.caa.co.za/information-for-the-public/fees/) schedule. Check that page for the current amounts."},{t:"h2",x:"Groups",id:"groups"},{t:"p",x:f},{t:"h2",x:"Cancelling or moving a booking",id:"cancel"},{t:"p",x:"If you need to cancel or move your appointment, please give at least 24 hours notice."},{t:"h2",x:"Which medical to book",id:"which"},{t:"ul",items:["[Class 2](/aviation-medicals/class-2/) for student and private pilots","[Cabin crew medical](/aviation-medicals/class-4-cabin-crew/), Class 4 or Class 2 as your operator asks","[Recreational Class 4](/aviation-medicals/recreational-pilots/) for microlight, gyroplane, light sport, glider and balloon pilots","[Renewal](/aviation-medicals/renewal/) of a Class 2 or Class 4"]},{t:"cta",x:"Book your aviation medical"}],airfields:[],bookService:null,bookLabel:"Book an aviation medical",related:["/aviation-medicals/class-2/","/aviation-medicals/class-4-cabin-crew/","/aviation-medicals/renewal/","/aviation-medicals/student-pilot/","/aviation-medicals/gauteng/","/aviation-medicals/midrand/"],guides:["renew-sacaa-class-2-medical","student-pilot-medical-south-africa","cabin-crew-medical-class-4-south-africa"],faqs:[{q:"How much is an aviation medical at ClinoTrend?",a:s},{q:"Does medical aid pay for an aviation medical?",a:"We accept most medical aids and charge medical aid rates. Whether your plan pays depends on your medical aid. Payment by EFT or card is required at the time of your visit."},{q:"Is the SACAA licence fee included?",a:"No. Licence fees are charged by SACAA and set out in its fees schedule."},{q:"Is there a cancellation fee?",a:"Please give at least 24 hours notice if you need to cancel or move your appointment. Contact the practice on 011 568 7979 about your booking."}],areaServed:["Gauteng","Midrand","Johannesburg","Pretoria"],keyword:"aviation medical cost",secondary:["how much is an aviation medical in south africa","class 2 medical cost","pilot medical price"],sources:[y.sacaaFees,i.register],llmsSummary:"Cost: aviation medicals at ClinoTrend start from R1,500, confirmed when you book. Extra tests or reports only if the doctor finds them needed. EFT or card at the visit, most medical aids at medical aid rates, self-pay quote first. SACAA licence fees are separate. Group bookings arranged in advance. 24 hours cancellation notice."}],w={path:"/local/",description:"Index of the ClinoTrend local area and aviation medical service pages, for review.",h1:"Local and service pages"},z=["Gauteng hub","Areas","Medicals"],X=Object.fromEntries(S.map(e=>[e.path,e])),P={rel:"noopener noreferrer",target:"_blank"},Q="2026-11-10";function Z(e){const n=[{name:"Home",path:"/"},{name:"Aviation medicals",path:"/aviation-medicals/"}];return e.kind==="area"&&e.path!=="/aviation-medicals/gauteng/"&&n.push({name:"Gauteng",path:"/aviation-medicals/gauteng/"}),n.push({name:e.trailName,path:e.path}),n}function E({trail:e}){return a.jsx("nav",{"aria-label":"Breadcrumb",className:"text-sm text-white/80 mb-4",children:a.jsx("ol",{className:"flex flex-wrap gap-1",children:e.map((n,r)=>a.jsxs("li",{className:"flex items-center gap-1",children:[r>0&&a.jsx("span",{"aria-hidden":"true",children:"/"}),r===e.length-1?a.jsx("span",{"aria-current":"page",className:"text-white",children:n.name}):a.jsx("a",{href:c(n.path),className:"underline underline-offset-2 hover:text-mint-300",children:n.name})]},`${n.path}-${r}`))})})}const aa=e=>e.bookService?`/book/?service=${e.bookService}`:"/book/",I=e=>e.replace(/^\/|\/$/g,"").repl